  let lets = (FStarC_List.collect (fun tmp -> (match tmp with
      | (b, a) -> (let tmp1 = (if (is_atomic a) then true else (if (FStarC_Custard_Syntax.is_pure (a).FStarC_Custard_Syntax.eff) then (let tmp1 = (count (b).FStarC_Custard_Syntax.b_name body) in
          (Prims.op_Less_Equals tmp1 (Prims.parse_int "1"))) else false)) in
        (if tmp1 then ((FStarC_SMap.add sm (b).FStarC_Custard_Syntax.b_name a);
        []) else (let v = (rename (b).FStarC_Custard_Syntax.b_name) in
        (FStarC_SMap.add sm (b).FStarC_Custard_Syntax.b_name { FStarC_Custard_Syntax.e = (FStarC_Custard_Syntax.EVar (v));
          ty = (a).FStarC_Custard_Syntax.ty;
          eff = (a).FStarC_Custard_Syntax.eff });
        ((v, (b).FStarC_Custard_Syntax.b_ty, a) :: []))))
    )) (FStarC_List.zip bs args)) in
  let r = (sub sm body) in
  let r1 = { FStarC_Custard_Syntax.e = (r).FStarC_Custard_Syntax.e;
      ty = (at).FStarC_Custard_Syntax.ty;
      eff = (at).FStarC_Custard_Syntax.eff } in
  (FStarC_List.fold_right (fun tmp acc -> (match tmp with
    | (v, ty, a) -> { FStarC_Custard_Syntax.e = (FStarC_Custard_Syntax.ELet (v, ty, a, acc));
        ty = (acc).FStarC_Custard_Syntax.ty;
        eff = (acc).FStarC_Custard_Syntax.eff }
  )) lets r1))

let rec inline_expr (tbl : (((FStarC_Custard_Syntax.binder) list * FStarC_Custard_Syntax.expr)) FStarC_SMap.t) (used : (bool) FStarC_SMap.t) (x : FStarC_Custard_Syntax.expr) : FStarC_Custard_Syntax.expr =
  (let g = (inline_expr tbl used) in
  (match (x).FStarC_Custard_Syntax.e with
    | (FStarC_Custard_Syntax.EApp ({ FStarC_Custard_Syntax.e = (FStarC_Custard_Syntax.EQual (n, tys)); ty = tmp; eff = tmp1; _ }, args)) -> (let args1 = (FStarC_List.map g args) in
      let tmp2 = (FStarC_Custard_Syntax.string_of_name n) in
      let tmp3 = (FStarC_SMap.try_find tbl tmp2) in
      (match tmp3 with
        | (Some ((bs, body))) when (Prims.op_Less_Equals (FStarC_List.length bs) (FStarC_List.length args1)) -> (let tmp4 = (FStarC_List.splitAt (FStarC_List.length bs) args1) in
          (match tmp4 with
            | (given, extra) -> (let r = (inline_call bs body given x) in
              (match extra with
                | [] -> r
                | tmp5 -> { FStarC_Custard_Syntax.e = (FStarC_Custard_Syntax.EApp (r, extra));
                    ty = (x).FStarC_Custard_Syntax.ty;
                    eff = (x).FStarC_Custard_Syntax.eff }
              ))
          ))
        | tmp4 -> (let tmp5 = (FStarC_Custard_Syntax.string_of_name n) in
          (FStarC_SMap.add used tmp5 true);
          { FStarC_Custard_Syntax.e = (FStarC_Custard_Syntax.EApp ({ FStarC_Custard_Syntax.e = (FStarC_Custard_Syntax.EQual (n, tys));
              ty = (x).FStarC_Custard_Syntax.ty;
              eff = (x).FStarC_Custard_Syntax.eff }, args1));
            ty = (x).FStarC_Custard_Syntax.ty;
            eff = (x).FStarC_Custard_Syntax.eff })
      ))
    | (FStarC_Custard_Syntax.EQual (n, tmp)) -> (let tmp1 = (FStarC_Custard_Syntax.string_of_name n) in
      let tmp2 = (FStarC_SMap.try_find tbl tmp1) in
      (match tmp2 with
        | (Some (([], body))) -> (inline_call [] body [] x)
        | tmp3 -> (let tmp4 = (FStarC_Custard_Syntax.string_of_name n) in
          (FStarC_SMap.add used tmp4 true);
          x)
      ))
    | tmp -> (FStarC_Custard_Syntax.map_children g x)
  ))

let rec inline_decls__fill (tbl : (((FStarC_Custard_Syntax.binder) list * FStarC_Custard_Syntax.expr)) FStarC_SMap.t) (used : (bool) FStarC_SMap.t) (inl : (FStarC_Custard_Syntax.dlet) FStarC_SMap.t) (visiting : (bool) FStarC_SMap.t) (bodies : (FStarC_Custard_Syntax.expr) FStarC_SMap.t) (n : string) : unit =
  (let tmp = (FStarC_SMap.try_find visiting n) in
  let tmp1 = (match tmp with
      | None -> true
      | tmp1 -> false
    ) in
  (if tmp1 then ((FStarC_SMap.add visiting n true);
  let tmp2 = (FStarC_SMap.try_find inl n) in
  (match tmp2 with
    | (Some (dl)) -> (let tmp3 = (decl_deps (FStarC_Custard_Syntax.DLet (dl))) in
      (FStarC_List.iter (inline_decls__fill tbl used inl visiting bodies) tmp3);
      let body = (inline_expr tbl used (dl).FStarC_Custard_Syntax.dl_body) in
      (FStarC_SMap.add bodies n body);
      (FStarC_SMap.add tbl n ((dl).FStarC_Custard_Syntax.dl_binders, body)))
    | None -> ()
  )) else ()))

let inline_decls (prog : (FStarC_Custard_Syntax.decl) list) : (FStarC_Custard_Syntax.decl) list =
  (let tbl = (FStarC_SMap.create (Prims.parse_int "50")) in
  let used = (FStarC_SMap.create (Prims.parse_int "50")) in
  let inl = (FStarC_SMap.create (Prims.parse_int "50")) in
  (FStarC_List.iter (fun d -> (match d with
    | (FStarC_Custard_Syntax.DLet (dl)) when (let tmp = (FStarC_List.existsb FStarC_Custard_Syntax.uu___is_Inline (dl).FStarC_Custard_Syntax.dl_flags) in
    (if tmp then true else (is_identity dl))) -> (let tmp = (FStarC_Custard_Syntax.string_of_name (dl).FStarC_Custard_Syntax.dl_name) in
      (FStarC_SMap.add inl tmp dl))
    | tmp -> ()
  )) prog);
  let visiting = (FStarC_SMap.create (Prims.parse_int "50")) in
  let bodies = (FStarC_SMap.create (Prims.parse_int "50")) in
  (FStarC_List.iter (fun d -> (match d with
    | (FStarC_Custard_Syntax.DLet (dl)) when (let tmp = (FStarC_List.existsb FStarC_Custard_Syntax.uu___is_Inline (dl).FStarC_Custard_Syntax.dl_flags) in
    (if tmp then true else (is_identity dl))) -> (let tmp = (FStarC_Custard_Syntax.string_of_name (dl).FStarC_Custard_Syntax.dl_name) in
      ((inline_decls__fill tbl used inl visiting bodies) tmp))
    | tmp -> ()
  )) prog);
  let prog1 = (FStarC_List.map (fun d -> (match d with
      | (FStarC_Custard_Syntax.DLet (dl)) -> (let tmp = (FStarC_Custard_Syntax.string_of_name (dl).FStarC_Custard_Syntax.dl_name) in
        let tmp1 = (FStarC_SMap.try_find bodies tmp) in
        (match tmp1 with
          | (Some (body)) -> (FStarC_Custard_Syntax.DLet ({ FStarC_Custard_Syntax.dl_name = (dl).FStarC_Custard_Syntax.dl_name;
              dl_typars = (dl).FStarC_Custard_Syntax.dl_typars;
              dl_binders = (dl).FStarC_Custard_Syntax.dl_binders;
              dl_ret = (dl).FStarC_Custard_Syntax.dl_ret;
              dl_eff = (dl).FStarC_Custard_Syntax.dl_eff;
              dl_body = body;
              dl_flags = (dl).FStarC_Custard_Syntax.dl_flags }))
          | None -> (let tmp2 = (inline_expr tbl used (dl).FStarC_Custard_Syntax.dl_body) in
            let tmp3 = { FStarC_Custard_Syntax.dl_name = (dl).FStarC_Custard_Syntax.dl_name;
                dl_typars = (dl).FStarC_Custard_Syntax.dl_typars;
                dl_binders = (dl).FStarC_Custard_Syntax.dl_binders;
                dl_ret = (dl).FStarC_Custard_Syntax.dl_ret;
                dl_eff = (dl).FStarC_Custard_Syntax.dl_eff;
                dl_body = tmp2;
                dl_flags = (dl).FStarC_Custard_Syntax.dl_flags } in
            (FStarC_Custard_Syntax.DLet (tmp3)))
        ))
      | d1 -> d1
    )) prog) in
  (FStarC_List.filter (fun d -> (match d with
    | (FStarC_Custard_Syntax.DLet (dl)) -> (let tmp = (FStarC_List.existsb FStarC_Custard_Syntax.uu___is_Inline (dl).FStarC_Custard_Syntax.dl_flags) in
      let tmp1 = (not tmp) in
      let tmp2 = (if tmp1 then true else (FStarC_List.existsb FStarC_Custard_Syntax.uu___is_Root (dl).FStarC_Custard_Syntax.dl_flags)) in
      (if tmp2 then true else (let tmp3 = (FStarC_Custard_Syntax.string_of_name (dl).FStarC_Custard_Syntax.dl_name) in
      let tmp4 = (FStarC_SMap.try_find used tmp3) in
      (match tmp4 with
        | (Some (v)) -> true
        | tmp5 -> false
      ))))
    | tmp -> true
  )) prog1))

let forwarder_table (prog : (FStarC_Custard_Syntax.decl) list) : ((Prims.int * Prims.int)) FStarC_SMap.t =
  (let t = (FStarC_SMap.create (Prims.parse_int "50")) in
  (FStarC_List.iter (fun d -> (match d with
    | (FStarC_Custard_Syntax.DLet (l)) when (if ((match (l).FStarC_Custard_Syntax.dl_binders with
      | (hd :: tl) -> true
      | tmp -> false
    ) && (FStarC_Custard_Syntax.is_pure (l).FStarC_Custard_Syntax.dl_eff)) then (let tmp = (FStarC_List.existsb FStarC_Custard_Syntax.uu___is_Rec (l).FStarC_Custard_Syntax.dl_flags) in
    (not tmp)) else false) -> (match ((l).FStarC_Custard_Syntax.dl_body).FStarC_Custard_Syntax.e with
        | (FStarC_Custard_Syntax.EVar (v)) -> (let n = (FStarC_List.length (l).FStarC_Custard_Syntax.dl_binders) in
          let found = (FStarC_List.fold_left (fun tmp b -> (match tmp with
              | (acc, k) -> ((if (((=) (b).FStarC_Custard_Syntax.b_name v) && (Prims.op_Less acc (Prims.parse_int "0"))) then k else acc), (Prims.op_Plus k (Prims.parse_int "1")))
            )) ((Prims.parse_int "-1"), (Prims.parse_int "0")) (l).FStarC_Custard_Syntax.dl_binders) in
          let found1 = (Custard_FStar_Pervasives_Native.fStar_Pervasives_Native_fst found) in
          (if (Prims.op_Greater_Equals found1 (Prims.parse_int "0")) then (let tmp = (FStarC_Custard_Syntax.string_of_name (l).FStarC_Custard_Syntax.dl_name) in
          (FStarC_SMap.add t tmp (n, found1))) else ()))
        | tmp -> ()
      )
    | tmp -> ()
  )) prog);
  t)

let forwarders : (((Prims.int * Prims.int)) FStarC_SMap.t ref) =
  (let tmp = (FStarC_SMap.create (Prims.parse_int "0")) in
  (ref tmp))

let beta (bs : (FStarC_Custard_Syntax.binder) list) (body : FStarC_Custard_Syntax.expr) (args : (FStarC_Custard_Syntax.expr) list) (at : FStarC_Custard_Syntax.expr) : FStarC_Custard_Syntax.expr =
  (let n = (FStarC_List.length bs) in
  (if (Prims.op_Less (FStarC_List.length args) n) then at else (let tmp = (FStarC_List.splitAt n args) in
  (match tmp with
    | (given, extra) -> (let r = (inline_call bs body given at) in
      (match extra with
        | [] -> r
        | tmp1 -> { FStarC_Custard_Syntax.e = (FStarC_Custard_Syntax.EApp (r, extra));
            ty = (at).FStarC_Custard_Syntax.ty;
            eff = (at).FStarC_Custard_Syntax.eff }
      ))
  ))))

let ctor_args_pure (e : FStarC_Custard_Syntax.expr) : bool =
  (match (e).FStarC_Custard_Syntax.e with
    | (FStarC_Custard_Syntax.ECtor (tmp, es)) -> (FStarC_List.for_all (fun a -> (FStarC_Custard_Syntax.is_pure (a).FStarC_Custard_Syntax.eff)) es)
    | (FStarC_Custard_Syntax.ETuple (es)) -> (FStarC_List.for_all (fun a -> (FStarC_Custard_Syntax.is_pure (a).FStarC_Custard_Syntax.eff)) es)
    | tmp -> false
  )

let rec match_pats (ps : (FStarC_Custard_Syntax.pat) list) (es : (FStarC_Custard_Syntax.expr) list) : (((string * FStarC_Custard_Syntax.expr)) list) option =
  (match (ps, es) with
    | ([], []) -> (Some ([]))
    | ((p :: ps1), (e :: es1)) -> (let tmp = (match_pat p e) in
      let tmp1 = (match_pats ps1 es1) in
      let tmp2 = (tmp, tmp1) in
      (match tmp2 with
        | ((Some (l1)), (Some (l2))) -> (Some ((FStarC_List.op_At l1 l2)))
        | tmp3 -> None
      ))
    | tmp -> None
  )

and match_pat (p : FStarC_Custard_Syntax.pat) (e : FStarC_Custard_Syntax.expr) : (((string * FStarC_Custard_Syntax.expr)) list) option =
  (match (p, (e).FStarC_Custard_Syntax.e) with
    | (FStarC_Custard_Syntax.PWild, tmp) -> (Some ([]))
    | ((FStarC_Custard_Syntax.PVar (v)), tmp) -> (Some (((v, e) :: [])))
    | ((FStarC_Custard_Syntax.PCtor (n, ps)), (FStarC_Custard_Syntax.ECtor (m, es))) -> (let tmp = (FStarC_Custard_Syntax.string_of_name n) in
      let tmp1 = (FStarC_Custard_Syntax.string_of_name m) in
      let tmp2 = ((=) tmp tmp1) in
      (if tmp2 then (match_pats ps es) else None))
    | ((FStarC_Custard_Syntax.PRecord (tmp, fs)), (FStarC_Custard_Syntax.ERecord (tmp1, es))) -> (FStarC_List.fold_left (fun acc tmp2 -> (match tmp2 with
        | (f, q) -> (let tmp3 = (FStarC_List.tryFind (fun tmp3 -> (match tmp3 with
              | (g, tmp4) -> ((=) g f)
            )) es) in
          let tmp4 = (acc, tmp3) in
          (match tmp4 with
            | ((Some (bs)), (Some ((tmp5, e1)))) -> (let tmp6 = (match_pat q e1) in
              (match tmp6 with
                | (Some (bs')) -> (Some ((FStarC_List.op_At bs bs')))
                | None -> None
              ))
            | tmp5 -> None
          ))
      )) (Some ([])) fs)
    | ((FStarC_Custard_Syntax.PTuple (ps)), (FStarC_Custard_Syntax.ETuple (es))) -> (match_pats ps es)
    | ((FStarC_Custard_Syntax.PConst (c1)), (FStarC_Custard_Syntax.EConst (c2))) -> (if (FStarC_Custard_Syntax.const_eq c1 c2) then (Some ([])) else None)
    | (tmp, tmp1) -> None
  )

let iota (brs : ((FStarC_Custard_Syntax.pat * (FStarC_Custard_Syntax.expr) option * FStarC_Custard_Syntax.expr)) list) (scrut : FStarC_Custard_Syntax.expr) (at : FStarC_Custard_Syntax.expr) : FStarC_Custard_Syntax.expr =
  (match brs with
    | [] -> at
    | ((p, None, body) :: brs1) -> (let tmp = (match_pat p scrut) in
      (match tmp with
        | None -> at
        | (Some (bnds)) -> (let tmp1 = (FStarC_List.map (fun tmp1 -> (match tmp1 with
              | (v, a) -> { FStarC_Custard_Syntax.b_name = v;
                  b_ty = (a).FStarC_Custard_Syntax.ty }
            )) bnds) in
          let tmp2 = (FStarC_List.map Custard_FStar_Pervasives_Native.fStar_Pervasives_Native_snd bnds) in
          (inline_call tmp1 body tmp2 at))
      ))
    | tmp -> at
  )

let rec called_only_list (v : string) (eta : (FStarC_Custard_Syntax.expr) list) : bool =
  (FStarC_List.for_all (called_only v) eta)

and called_only (v : string) (x : FStarC_Custard_Syntax.expr) : bool =
  (let tmp = (occurs v x) in
  let tmp1 = (not tmp) in
  (if tmp1 then true else (match (x).FStarC_Custard_Syntax.e with
    | (FStarC_Custard_Syntax.EVar (tmp2)) -> false
    | (FStarC_Custard_Syntax.EApp (h, es)) -> (match (h).FStarC_Custard_Syntax.e with
        | (FStarC_Custard_Syntax.EVar (w)) -> (if ((=) w v) then (called_only_list v es) else false)
        | tmp2 -> (let tmp3 = (called_only v h) in
          (if tmp3 then (called_only_list v es) else false))
      )
    | tmp2 -> (FStarC_Custard_Syntax.for_all_children (called_only v) x)
  )))

let rec reeval (e : FStarC_Custard_Syntax.expr) : bool =
  (if (FStarC_Custard_Syntax.is_pure (e).FStarC_Custard_Syntax.eff) then (match (e).FStarC_Custard_Syntax.e with
    | (FStarC_Custard_Syntax.EVar (tmp)) -> true
    | (FStarC_Custard_Syntax.EConst (tmp)) -> true
    | (FStarC_Custard_Syntax.EQual (u__1, u__2)) -> true
    | (FStarC_Custard_Syntax.EProj (a, tmp, tmp1)) -> (reeval a)
    | (FStarC_Custard_Syntax.EDiscrim (a, tmp)) -> (reeval a)
    | (FStarC_Custard_Syntax.ECast (a, tmp)) -> (reeval a)
    | (FStarC_Custard_Syntax.ECoerce (a, tmp)) -> (reeval a)
    | (FStarC_Custard_Syntax.EOp (tmp, es)) -> (FStarC_List.for_all reeval es)
    | (FStarC_Custard_Syntax.ECtor (tmp, es)) -> (FStarC_List.for_all reeval es)
    | (FStarC_Custard_Syntax.ETuple (es)) -> (FStarC_List.for_all reeval es)
    | (FStarC_Custard_Syntax.ERecord (tmp, fs)) -> (FStarC_List.for_all (fun tmp1 -> (match tmp1 with
        | (tmp2, e1) -> (reeval e1)
      )) fs)
    | tmp -> false
  ) else false)

let rec destructed_only (v : string) (x : FStarC_Custard_Syntax.expr) : bool =
  (let g = (destructed_only v) in
  let scrut = (fun s -> (match (s).FStarC_Custard_Syntax.e with
      | (FStarC_Custard_Syntax.EVar (w)) -> ((=) w v)
      | tmp -> (g s)
    )) in
  let brs_ok = (fun brs -> (FStarC_List.for_all (fun b -> (match b with
      | (tmp, gd, bd) -> (let tmp1 = (match gd with
            | (Some (gd1)) -> (g gd1)
            | None -> true
          ) in
        (if tmp1 then (g bd) else false))
    )) brs)) in
  (match (x).FStarC_Custard_Syntax.e with
    | (FStarC_Custard_Syntax.EVar (w)) -> ((<>) w v)
    | (FStarC_Custard_Syntax.EProj (e1, tmp, tmp1)) -> (match (e1).FStarC_Custard_Syntax.e with
        | (FStarC_Custard_Syntax.EVar (w)) -> (if ((=) w v) then true else (g e1))
        | tmp2 -> (g e1)
      )
    | (FStarC_Custard_Syntax.EMatch (s, brs)) -> (let tmp = (scrut s) in
      (if tmp then (brs_ok brs) else false))
    | (FStarC_Custard_Syntax.ETry (s, brs)) -> (let tmp = (g s) in
      (if tmp then (brs_ok brs) else false))
    | tmp -> (FStarC_Custard_Syntax.for_all_children g x)
  ))

let rec reduce_branch (br : (FStarC_Custard_Syntax.pat * (FStarC_Custard_Syntax.expr) option * FStarC_Custard_Syntax.expr)) : (FStarC_Custard_Syntax.pat * (FStarC_Custard_Syntax.expr) option * FStarC_Custard_Syntax.expr) =
  (match br with
    | (p, g, b) -> (let tmp = (match g with
          | None -> None
          | (Some (g1)) -> (let tmp = (reduce g1) in
            (Some (tmp)))
        ) in
      let tmp1 = (reduce b) in
      (p, tmp, tmp1))
  )

and reduce (x : FStarC_Custard_Syntax.expr) : FStarC_Custard_Syntax.expr =
  (match (x).FStarC_Custard_Syntax.e with
    | (FStarC_Custard_Syntax.EApp (h, args)) -> (let h1 = (reduce h) in
      let args1 = (FStarC_List.map reduce args) in
      (match (h1).FStarC_Custard_Syntax.e with
        | (FStarC_Custard_Syntax.EFun (bs, body)) when (Prims.op_Less_Equals (FStarC_List.length bs) (FStarC_List.length args1)) -> (let tmp = (beta bs body args1 { FStarC_Custard_Syntax.e = (FStarC_Custard_Syntax.EApp (h1, args1));
              ty = (x).FStarC_Custard_Syntax.ty;
              eff = (x).FStarC_Custard_Syntax.eff }) in
          (reduce tmp))
        | (FStarC_Custard_Syntax.EQual (n, tmp)) when (let tmp1 = (!(forwarders)) in
        let tmp2 = (FStarC_Custard_Syntax.string_of_name n) in
        let tmp3 = (FStarC_SMap.try_find tmp1 tmp2) in
        (match tmp3 with
          | (Some ((a, tmp4))) -> (if ((=) a (FStarC_List.length args1)) then (FStarC_List.for_all (fun e -> (FStarC_Custard_Syntax.is_pure (e).FStarC_Custard_Syntax.eff)) args1) else false)
          | None -> false
        )) -> (let tmp1 = (!(forwarders)) in
          let tmp2 = (FStarC_Custard_Syntax.string_of_name n) in
          let tmp3 = (FStarC_SMap.try_find tmp1 tmp2) in
          let tmp4 = (match tmp3 with
              | (Some (v)) -> v
            ) in
          (match tmp4 with
            | (tmp5, i) -> (let arg = (FStarC_List.nth args1 i) in
              { FStarC_Custard_Syntax.e = (arg).FStarC_Custard_Syntax.e;
                ty = (x).FStarC_Custard_Syntax.ty;
                eff = (arg).FStarC_Custard_Syntax.eff })
          ))
        | tmp -> { FStarC_Custard_Syntax.e = (FStarC_Custard_Syntax.EApp (h1, args1));
            ty = (x).FStarC_Custard_Syntax.ty;
            eff = (x).FStarC_Custard_Syntax.eff }
      ))
    | (FStarC_Custard_Syntax.EMatch (scrut, brs)) -> (let scrut1 = (reduce scrut) in
      let tmp = (ctor_args_pure scrut1) in
      (if tmp then (let tmp1 = (FStarC_List.map reduce_branch brs) in
      let tmp2 = (scrut1, tmp1) in
      let tmp3 = (FStarC_Custard_Syntax.EMatch ((match tmp2 with (custard_tup, _) -> custard_tup), (match tmp2 with (_, custard_tup) -> custard_tup))) in
      let tmp4 = { FStarC_Custard_Syntax.e = tmp3;
          ty = (x).FStarC_Custard_Syntax.ty;
          eff = (x).FStarC_Custard_Syntax.eff } in
      let r = (iota brs scrut1 tmp4) in
      (match (r).FStarC_Custard_Syntax.e with
        | (FStarC_Custard_Syntax.EMatch (u__1, u__2)) -> r
        | tmp5 -> (reduce r)
      )) else (let tmp1 = (FStarC_List.map reduce_branch brs) in
      let tmp2 = (scrut1, tmp1) in
      let tmp3 = (FStarC_Custard_Syntax.EMatch ((match tmp2 with (custard_tup, _) -> custard_tup), (match tmp2 with (_, custard_tup) -> custard_tup))) in
      { FStarC_Custard_Syntax.e = tmp3;
        ty = (x).FStarC_Custard_Syntax.ty;
        eff = (x).FStarC_Custard_Syntax.eff })))
    | (FStarC_Custard_Syntax.EConst (tmp)) -> x
    | (FStarC_Custard_Syntax.EVar (tmp)) -> x
