  (match br with
    | (p, gd, b) -> (let sm = (FStarC_SMap.create (Prims.parse_int "10")) in
      let lets = (ref []) in
      let free = (fun v -> (let tmp = (count v b) in
        let tmp1 = (match gd with
            | None -> (Prims.parse_int "0")
            | (Some (g)) -> (count v g)
          ) in
        let uses = (Prims.op_Plus tmp tmp1) in
        (if (Prims.op_Less_Equals uses (Prims.parse_int "1")) then true else (let tmp2 = (only_projected v b) in
        (if tmp2 then (match gd with
          | None -> true
          | (Some (g)) -> (only_projected v g)
        ) else false))))) in
      let p1 = ((inline_fields__go_branch__go_pat plan sm lets free) p) in
      let gsm = (FStarC_SMap.create (Prims.parse_int "10")) in
