    | (FStarC_Custard_Syntax.PTuple (ps)) -> (FStarC_List.existsb (rebinds__pv v) ps)
    | (FStarC_Custard_Syntax.POr (ps)) -> (FStarC_List.existsb (rebinds__pv v) ps)
    | (FStarC_Custard_Syntax.PRecord (tmp, fs)) -> (FStarC_List.existsb (fun tmp1 -> (match tmp1 with
        | (tmp2, q) -> ((rebinds__pv v) q)
      )) fs)
    | tmp -> false
  )

let rec rebinds (v : string) (x : FStarC_Custard_Syntax.expr) : bool =
  (let g = (rebinds v) in
  let br = (fun r -> (match r with
      | (p, gd, b) -> (let tmp = ((rebinds__pv v) p) in
        let tmp1 = (if tmp then true else (match gd with
            | (Some (gd1)) -> (g gd1)
            | None -> false
          )) in
        (if tmp1 then true else (g b)))
    )) in
  (match (x).FStarC_Custard_Syntax.e with
    | (FStarC_Custard_Syntax.ELet (w, tmp, e1, e2)) -> (let tmp1 = (if ((=) w v) then true else (g e1)) in
      (if tmp1 then true else (g e2)))
    | (FStarC_Custard_Syntax.EFun (bs, b)) -> (let tmp = (FStarC_List.existsb (fun b1 -> ((=) (b1).FStarC_Custard_Syntax.b_name v)) bs) in
      (if tmp then true else (g b)))
    | (FStarC_Custard_Syntax.EMatch (sc, brs)) -> (let tmp = (g sc) in
      (if tmp then true else (FStarC_List.existsb br brs)))
    | (FStarC_Custard_Syntax.ETry (a, brs)) -> (let tmp = (g a) in
      (if tmp then true else (FStarC_List.existsb br brs)))
    | tmp -> (FStarC_Custard_Syntax.exists_child g x)
  ))

let rec unbuild (infos : (ctor_info) FStarC_SMap.t) (x : FStarC_Custard_Syntax.expr) : FStarC_Custard_Syntax.expr =
  (let g = (unbuild infos) in
  let pick = (fun fs f -> (let tmp = (FStarC_List.for_all (fun tmp -> (match tmp with
        | (h, e) -> (((=) h f) || (FStarC_Custard_Syntax.is_pure (e).FStarC_Custard_Syntax.eff))
      )) fs) in
    (if tmp then (let tmp1 = (FStarC_List.tryFind (fun tmp1 -> (match tmp1 with
        | (h, tmp2) -> ((=) h f)
      )) fs) in
    (match tmp1 with
      | (Some ((tmp2, e))) -> (Some (e))
      | None -> None
    )) else None))) in
  (match (x).FStarC_Custard_Syntax.e with
    | (FStarC_Custard_Syntax.EProj (e1, n, f)) -> (let e11 = (g e1) in
      let alt = { FStarC_Custard_Syntax.e = (FStarC_Custard_Syntax.EProj (e11, n, f));
          ty = (x).FStarC_Custard_Syntax.ty;
          eff = (x).FStarC_Custard_Syntax.eff } in
      (match (e11).FStarC_Custard_Syntax.e with
        | (FStarC_Custard_Syntax.ERecord (tmp, fs)) -> (let tmp1 = (pick fs f) in
          (match tmp1 with
            | (Some (e)) -> e
            | None -> alt
          ))
        | (FStarC_Custard_Syntax.ECtor (cn, es)) -> (let tmp = (FStarC_Custard_Syntax.string_of_name cn) in
          let tmp1 = (FStarC_SMap.try_find infos tmp) in
          (match tmp1 with
            | (Some (ci)) -> (if ((<>) (FStarC_List.length es) (FStarC_List.length (ci).ci_fields)) then alt else (let tmp2 = (FStarC_List.map Custard_FStar_Pervasives_Native.fStar_Pervasives_Native_fst (ci).ci_fields) in
              let tmp3 = (FStarC_List.zip tmp2 es) in
              let tmp4 = (pick tmp3 f) in
              (match tmp4 with
                | (Some (e)) -> e
                | None -> alt
              )))
            | None -> alt
          ))
        | tmp -> alt
      ))
    | (FStarC_Custard_Syntax.ELet (v, t, rhs, b)) -> (let rhs1 = (g rhs) in
      let b1 = (g b) in
      let alt = { FStarC_Custard_Syntax.e = (FStarC_Custard_Syntax.ELet (v, t, rhs1, b1));
          ty = (x).FStarC_Custard_Syntax.ty;
          eff = (x).FStarC_Custard_Syntax.eff } in
      let fields = (match (rhs1).FStarC_Custard_Syntax.e with
          | (FStarC_Custard_Syntax.ERecord (tmp, fs)) -> (Some (fs))
          | (FStarC_Custard_Syntax.ECtor (cn, es)) -> (let tmp = (FStarC_Custard_Syntax.string_of_name cn) in
            let tmp1 = (FStarC_SMap.try_find infos tmp) in
            (match tmp1 with
              | (Some (ci)) -> (if ((=) (FStarC_List.length es) (FStarC_List.length (ci).ci_fields)) then (let tmp2 = (FStarC_List.map Custard_FStar_Pervasives_Native.fStar_Pervasives_Native_fst (ci).ci_fields) in
                let tmp3 = (FStarC_List.zip tmp2 es) in
                (Some (tmp3))) else None)
              | None -> None
            ))
          | tmp -> None
        ) in
      (match fields with
        | (Some (fs)) when (let tmp = (FStarC_List.for_all (fun tmp -> (match tmp with
            | (tmp1, e) -> (reeval e)
          )) fs) in
        let tmp1 = (if tmp then (only_projected v b1) else false) in
        (if tmp1 then (let tmp2 = (rebinds v b1) in
        (not tmp2)) else false)) -> (let sm = (FStarC_SMap.create (Prims.parse_int "1")) in
          (FStarC_SMap.add sm v rhs1);
          let tmp = (psub sm b1) in
          (g tmp))
        | tmp -> alt
      ))
    | tmp -> (FStarC_Custard_Syntax.map_children g x)
  ))

