let same_vars (ps : (FStarC_Custard_Syntax.pat) list) (es : (FStarC_Custard_Syntax.expr) list) : bool =
  (if ((=) (FStarC_List.length ps) (FStarC_List.length es)) then (FStarC_List.for_all (fun tmp -> (match tmp with
