  (match br with
    | (p, None, body) -> (match (p, (body).FStarC_Custard_Syntax.e) with
        | ((FStarC_Custard_Syntax.PCtor (cn, ps)), (FStarC_Custard_Syntax.ECtor (dn, es))) when (let tmp = (FStarC_Custard_Syntax.string_of_name cn) in
        let tmp1 = (FStarC_Custard_Syntax.string_of_name dn) in
        let tmp2 = ((=) tmp tmp1) in
        (if tmp2 then (same_vars ps es) else false)) -> (let tmp = (FStarC_Custard_Syntax.string_of_name cn) in
          (Some (tmp)))
        | ((FStarC_Custard_Syntax.PRecord (tn, fps)), (FStarC_Custard_Syntax.ERecord (rn, fes))) when (let tmp = (FStarC_Custard_Syntax.string_of_name tn) in
        let tmp1 = (FStarC_Custard_Syntax.string_of_name rn) in
        let tmp2 = ((=) tmp tmp1) in
        let tmp3 = (if tmp2 then ((=) (FStarC_List.length fps) (FStarC_List.length fes)) else false) in
        let tmp4 = (if tmp3 then (FStarC_List.for_all (fun tmp4 -> (match tmp4 with
            | ((f, tmp5), (g, tmp6)) -> ((=) f g)
          )) (FStarC_List.zip fps fes)) else false) in
        (if tmp4 then (let tmp5 = (FStarC_List.map Custard_FStar_Pervasives_Native.fStar_Pervasives_Native_snd fps) in
        let tmp6 = (FStarC_List.map Custard_FStar_Pervasives_Native.fStar_Pervasives_Native_snd fes) in
        (same_vars tmp5 tmp6)) else false)) -> (let tmp = (FStarC_Custard_Syntax.string_of_name tn) in
          (Some (tmp)))
        | (FStarC_Custard_Syntax.PWild, (FStarC_Custard_Syntax.EVar (w))) when (scrut_var w) -> (Some (""))
        | ((FStarC_Custard_Syntax.PVar (u)), (FStarC_Custard_Syntax.EVar (w))) when (if ((=) u w) then true else (scrut_var w)) -> (Some (""))
        | tmp -> None
      )
    | tmp -> None
  ))

let rec rebuild_id__go (s : FStarC_Custard_Syntax.expr) (bs : ((FStarC_Custard_Syntax.pat * (FStarC_Custard_Syntax.expr) option * FStarC_Custard_Syntax.expr)) list) (acc : (string) list) : ((string) list) option =
  (match bs with
    | [] -> (Some (acc))
    | (b :: rest) -> (let tmp = (id_branch s b) in
      (match tmp with
        | (Some (c)) -> ((rebuild_id__go s) rest (c :: acc))
        | None -> None
      ))
  )

let covers_type (cs : (string) list) : bool =
  (let tmp = (FStarC_List.existsb (fun c -> ((=) c "")) cs) in
  (if tmp then true else (match cs with
    | [] -> false
    | (c0 :: tmp1) -> (let tmp2 = (FStarC_SMap.try_find ctor_family c0) in
      (match tmp2 with
        | (Some (all)) -> (FStarC_List.for_all (fun c -> (FStarC_List.existsb (fun d -> ((=) d c)) cs)) all)
        | None -> ((=) (FStarC_List.length cs) (Prims.parse_int "1"))
      ))
  )))

let rebuild_id (s : FStarC_Custard_Syntax.expr) (brs : ((FStarC_Custard_Syntax.pat * (FStarC_Custard_Syntax.expr) option * FStarC_Custard_Syntax.expr)) list) : (FStarC_Custard_Syntax.expr) option =
  (let tmp = ((rebuild_id__go s) brs []) in
  (match tmp with
    | (Some (cs)) -> (let tmp1 = (covers_type cs) in
      (if tmp1 then (Some (s)) else None))
    | None -> None
  ))

let bool_alt (p : FStarC_Custard_Syntax.pat) (body : FStarC_Custard_Syntax.expr) : ((bool) option) option =
  (match p with
    | (FStarC_Custard_Syntax.PConst ((FStarC_Custard_Syntax.CBool (b)))) -> (Some ((Some (b))))
    | FStarC_Custard_Syntax.PWild -> (Some (None))
    | (FStarC_Custard_Syntax.PVar (v)) -> (let tmp = (occurs v body) in
      (if tmp then None else (Some (None))))
    | tmp -> None
  )

let as_if (brs : ((FStarC_Custard_Syntax.pat * (FStarC_Custard_Syntax.expr) option * FStarC_Custard_Syntax.expr)) list) : ((FStarC_Custard_Syntax.expr * FStarC_Custard_Syntax.expr)) option =
  (match brs with
    | ((p1, None, b1) :: ((p2, None, b2) :: [])) -> (let tmp = (bool_alt p1 b1) in
      let tmp1 = (bool_alt p2 b2) in
      let tmp2 = (tmp, tmp1) in
      (match tmp2 with
        | ((Some ((Some (c1)))), (Some (alt2))) -> (let complementary = (match alt2 with
              | None -> true
              | (Some (c2)) -> ((<>) c1 c2)
            ) in
          (if (not complementary) then None else (if c1 then (Some ((b1, b2))) else (Some ((b2, b1))))))
        | tmp3 -> None
      ))
    | tmp -> None
  )

let fields_of (n : FStarC_Custard_Syntax.name) : ((string) list) option =
  (let tmp = (FStarC_Custard_Syntax.string_of_name n) in
  (FStarC_SMap.try_find one_ctor tmp))

let proj_spine (n : FStarC_Custard_Syntax.name) (fs : (string) list) (es : (FStarC_Custard_Syntax.expr) list) : (FStarC_Custard_Syntax.expr) option =
  (if ((match fs with
    | [] -> true
    | tmp -> false
  ) || ((<>) (FStarC_List.length fs) (FStarC_List.length es))) then None else (let base = (ref None) in
  let ok = (FStarC_List.for_all (fun tmp -> (match tmp with
      | (f, e) -> (match (e).FStarC_Custard_Syntax.e with
          | (FStarC_Custard_Syntax.EProj (s, pn, g)) -> (let tmp1 = (if ((=) g f) then (let tmp1 = (FStarC_Custard_Syntax.string_of_name pn) in
              let tmp2 = (FStarC_Custard_Syntax.string_of_name n) in
              ((=) tmp1 tmp2)) else false) in
            (if tmp1 then (let tmp2 = (!(base)) in
            let tmp3 = ((s).FStarC_Custard_Syntax.e, tmp2) in
            (match tmp3 with
              | ((FStarC_Custard_Syntax.EVar (v)), None) -> (((base) := (Some (s)));
                true)
              | ((FStarC_Custard_Syntax.EVar (v)), (Some (b))) -> (match (b).FStarC_Custard_Syntax.e with
                  | (FStarC_Custard_Syntax.EVar (w)) -> ((=) v w)
                  | tmp4 -> false
                )
              | tmp4 -> false
            )) else false))
          | tmp1 -> false
        )
    )) (FStarC_List.zip fs es)) in
  (if ok then (!(base)) else None)))

let rebuild_proj_id (x : FStarC_Custard_Syntax.expr) : (FStarC_Custard_Syntax.expr) option =
  (match (x).FStarC_Custard_Syntax.e with
    | (FStarC_Custard_Syntax.ECtor (n, es)) -> (let tmp = (fields_of n) in
      (match tmp with
        | (Some (fs)) -> (proj_spine n fs es)
        | None -> None
      ))
    | (FStarC_Custard_Syntax.ERecord (n, fs)) -> (let tmp = (FStarC_List.map Custard_FStar_Pervasives_Native.fStar_Pervasives_Native_fst fs) in
      let tmp1 = (FStarC_List.map Custard_FStar_Pervasives_Native.fStar_Pervasives_Native_snd fs) in
      (proj_spine n tmp tmp1))
    | (FStarC_Custard_Syntax.ETuple (es)) -> (match es with
        | [] -> None
        | (e0 :: tmp) -> (match (e0).FStarC_Custard_Syntax.e with
            | (FStarC_Custard_Syntax.EProj (tmp1, n, tmp2)) -> (let tmp3 = (FStarC_List.mapi (fun i tmp3 -> (Prims.strcat "_" (Prims.string_of_int (Prims.op_Plus i (Prims.parse_int "1"))))) es) in
              (proj_spine n tmp3 es))
            | tmp1 -> None
          )
      )
    | tmp -> None
  )

let rec simpl_branch (br : (FStarC_Custard_Syntax.pat * (FStarC_Custard_Syntax.expr) option * FStarC_Custard_Syntax.expr)) : (FStarC_Custard_Syntax.pat * (FStarC_Custard_Syntax.expr) option * FStarC_Custard_Syntax.expr) =
  (match br with
    | (p, g, b) -> (let tmp = (match g with
          | None -> None
          | (Some (g1)) -> (let tmp = (simpl g1) in
            (Some (tmp)))
        ) in
      let tmp1 = (simpl b) in
      (p, tmp, tmp1))
  )

and simpl (x : FStarC_Custard_Syntax.expr) : FStarC_Custard_Syntax.expr =
  (match (x).FStarC_Custard_Syntax.e with
    | (FStarC_Custard_Syntax.ELet (v, ty, e1, e2)) -> (let e11 = (simpl e1) in
      let e21 = (simpl e2) in
      (float_lets x e11 (fun e12 -> (if (match (e21).FStarC_Custard_Syntax.e with
        | (FStarC_Custard_Syntax.EVar (w)) -> ((=) w v)
        | tmp -> false
      ) then e12 else (if (match (e12).FStarC_Custard_Syntax.e with
        | (FStarC_Custard_Syntax.EVar (w)) -> ((<>) w v)
        | tmp -> false
      ) then (let w = (match (e12).FStarC_Custard_Syntax.e with
          | (FStarC_Custard_Syntax.EVar (w)) -> w
          | tmp -> v
        ) in
      (rename_var v w e21)) else (let tmp = (occurs v e21) in
      (if tmp then { FStarC_Custard_Syntax.e = (FStarC_Custard_Syntax.ELet (v, ty, e12, e21));
        ty = (x).FStarC_Custard_Syntax.ty;
        eff = (x).FStarC_Custard_Syntax.eff } else (let tmp1 = (FStarC_Custard_Syntax.is_droppable e12) in
      (if tmp1 then e21 else { FStarC_Custard_Syntax.e = (FStarC_Custard_Syntax.ESeq (e12, e21));
        ty = (x).FStarC_Custard_Syntax.ty;
        eff = (x).FStarC_Custard_Syntax.eff })))))))))
    | (FStarC_Custard_Syntax.ESeq (e1, e2)) -> (let e11 = (simpl e1) in
      let e21 = (simpl e2) in
      (float_lets x e11 (fun e12 -> (let tmp = (FStarC_Custard_Syntax.is_droppable e12) in
      (if tmp then e21 else { FStarC_Custard_Syntax.e = (FStarC_Custard_Syntax.ESeq (e12, e21));
        ty = (x).FStarC_Custard_Syntax.ty;
        eff = (x).FStarC_Custard_Syntax.eff })))))
    | (FStarC_Custard_Syntax.EMatch (s, brs)) -> (let s1 = (simpl s) in
      let brs1 = (FStarC_List.map simpl_branch brs) in
      let tmp = (rebuild_id s1 brs1) in
      (match tmp with
        | (Some (r)) -> r
        | None -> (let tmp1 = (as_if brs1) in
          (match tmp1 with
            | (Some ((t, f))) -> { FStarC_Custard_Syntax.e = (FStarC_Custard_Syntax.EIf (s1, t, f));
                ty = (x).FStarC_Custard_Syntax.ty;
                eff = (x).FStarC_Custard_Syntax.eff }
            | None -> { FStarC_Custard_Syntax.e = (FStarC_Custard_Syntax.EMatch (s1, brs1));
                ty = (x).FStarC_Custard_Syntax.ty;
                eff = (x).FStarC_Custard_Syntax.eff }
          ))
      ))
    | (FStarC_Custard_Syntax.ECtor (n, es)) -> (let tmp = (FStarC_List.map simpl es) in
      let tmp1 = (n, tmp) in
      let tmp2 = (FStarC_Custard_Syntax.ECtor ((match tmp1 with (custard_tup, _) -> custard_tup), (match tmp1 with (_, custard_tup) -> custard_tup))) in
      let r = { FStarC_Custard_Syntax.e = tmp2;
          ty = (x).FStarC_Custard_Syntax.ty;
          eff = (x).FStarC_Custard_Syntax.eff } in
      let tmp3 = (rebuild_proj_id r) in
      (match tmp3 with
        | (Some (s)) -> s
        | None -> r
      ))
    | (FStarC_Custard_Syntax.ETuple (es)) -> (let tmp = (FStarC_List.map simpl es) in
      let tmp1 = (FStarC_Custard_Syntax.ETuple (tmp)) in
      let r = { FStarC_Custard_Syntax.e = tmp1;
          ty = (x).FStarC_Custard_Syntax.ty;
          eff = (x).FStarC_Custard_Syntax.eff } in
      let tmp2 = (rebuild_proj_id r) in
      (match tmp2 with
        | (Some (s)) -> s
        | None -> r
      ))
    | (FStarC_Custard_Syntax.ERecord (n, fs)) -> (let tmp = (FStarC_List.map (fun tmp -> (match tmp with
          | (f, e) -> (let tmp1 = (simpl e) in
            (f, tmp1))
        )) fs) in
      let tmp1 = (n, tmp) in
      let tmp2 = (FStarC_Custard_Syntax.ERecord ((match tmp1 with (custard_tup, _) -> custard_tup), (match tmp1 with (_, custard_tup) -> custard_tup))) in
      let r = { FStarC_Custard_Syntax.e = tmp2;
          ty = (x).FStarC_Custard_Syntax.ty;
          eff = (x).FStarC_Custard_Syntax.eff } in
      let tmp3 = (rebuild_proj_id r) in
      (match tmp3 with
        | (Some (s)) -> s
        | None -> r
      ))
    | (FStarC_Custard_Syntax.ECast (e1, c)) -> (let e11 = (simpl e1) in
      (match ((e11).FStarC_Custard_Syntax.e, c) with
        | ((FStarC_Custard_Syntax.EConst ((FStarC_Custard_Syntax.CInt (n, tmp, tmp1)))), (FStarC_Custard_Syntax.TFloat (fw))) -> (match (FStarC_Custard_Syntax.float_lit_of_int fw n) with
            | (Some (f)) -> { FStarC_Custard_Syntax.e = (FStarC_Custard_Syntax.EConst ((FStarC_Custard_Syntax.CFloat (f, fw))));
                ty = (x).FStarC_Custard_Syntax.ty;
                eff = (x).FStarC_Custard_Syntax.eff }
            | None -> { FStarC_Custard_Syntax.e = (FStarC_Custard_Syntax.ECast (e11, c));
                ty = (x).FStarC_Custard_Syntax.ty;
                eff = (x).FStarC_Custard_Syntax.eff }
          )
        | tmp -> { FStarC_Custard_Syntax.e = (FStarC_Custard_Syntax.ECast (e11, c));
            ty = (x).FStarC_Custard_Syntax.ty;
            eff = (x).FStarC_Custard_Syntax.eff }
      ))
    | tmp -> (FStarC_Custard_Syntax.map_children simpl x)
  )

let decl_arity (prog : (FStarC_Custard_Syntax.decl) list) : (Prims.int) FStarC_SMap.t =
  (let tbl = (FStarC_SMap.create (Prims.parse_int "100")) in
  (FStarC_List.iter (fun d -> (match d with
    | (FStarC_Custard_Syntax.DLet (l)) -> (let tmp = (FStarC_Custard_Syntax.string_of_name (l).FStarC_Custard_Syntax.dl_name) in
      let tmp1 = (if (match (l).FStarC_Custard_Syntax.dl_binders with
          | (hd :: tl) -> true
          | tmp1 -> false
        ) then (FStarC_List.length (l).FStarC_Custard_Syntax.dl_binders) else (arrow_arity (l).FStarC_Custard_Syntax.dl_ret)) in
      (FStarC_SMap.add tbl tmp tmp1))
    | (FStarC_Custard_Syntax.DExternal (x)) -> (let tmp = (FStarC_Custard_Syntax.string_of_name (x).FStarC_Custard_Syntax.dx_name) in
      let tmp1 = (arrow_arity (x).FStarC_Custard_Syntax.dx_ty) in
      (FStarC_SMap.add tbl tmp tmp1))
    | tmp -> ()
  )) prog);
  tbl)

let rec cheap_expr (x : FStarC_Custard_Syntax.expr) : bool =
  (if (FStarC_Custard_Syntax.is_pure (x).FStarC_Custard_Syntax.eff) then (match (x).FStarC_Custard_Syntax.e with
    | (FStarC_Custard_Syntax.EConst (tmp)) -> true
    | (FStarC_Custard_Syntax.EVar (tmp)) -> true
    | (FStarC_Custard_Syntax.EQual (u__1, u__2)) -> true
    | (FStarC_Custard_Syntax.EApp (f, args)) -> (let tmp = (cheap_expr f) in
      (if tmp then (FStarC_List.for_all cheap_expr args) else false))
    | (FStarC_Custard_Syntax.ECast (e, tmp)) -> (cheap_expr e)
    | (FStarC_Custard_Syntax.ECoerce (e, tmp)) -> (cheap_expr e)
    | (FStarC_Custard_Syntax.EProj (e, tmp, tmp1)) -> (cheap_expr e)
    | (FStarC_Custard_Syntax.EFun (u__1, u__2)) -> true
    | (FStarC_Custard_Syntax.EOp (tmp, es)) -> (FStarC_List.for_all cheap_expr es)
    | (FStarC_Custard_Syntax.ECtor (tmp, es)) -> (FStarC_List.for_all cheap_expr es)
    | (FStarC_Custard_Syntax.ETuple (es)) -> (FStarC_List.for_all cheap_expr es)
    | (FStarC_Custard_Syntax.ERecord (tmp, fs)) -> (FStarC_List.for_all (fun tmp1 -> (match tmp1 with
        | (tmp2, e) -> (cheap_expr e)
      )) fs)
    | (FStarC_Custard_Syntax.EDiscrim (e, tmp)) -> (cheap_expr e)
    | tmp -> false
  ) else false)

let rec expr_uses (acc : (Prims.int) FStarC_SMap.t) (x : FStarC_Custard_Syntax.expr) : unit =
  (let note = (fun n k -> (let s = (FStarC_Custard_Syntax.string_of_name n) in
    let tmp = (FStarC_SMap.try_find acc s) in
    (match tmp with
      | (Some (m)) when (Prims.op_Less_Equals m k) -> ()
      | tmp1 -> (FStarC_SMap.add acc s k)
    ))) in
  let sub_ = (fun es -> (FStarC_List.iter (expr_uses acc) es)) in
  (match (x).FStarC_Custard_Syntax.e with
    | (FStarC_Custard_Syntax.EApp ({ FStarC_Custard_Syntax.e = (FStarC_Custard_Syntax.EQual (n, tmp)); ty = tmp1; eff = tmp2; _ }, es)) -> ((note n (FStarC_List.length es));
      (sub_ es))
    | (FStarC_Custard_Syntax.EQual (n, tmp)) -> (note n (Prims.parse_int "0"))
    | tmp -> (FStarC_Custard_Syntax.iter_children (expr_uses acc) x)
  ))

let use_arity (prog : (FStarC_Custard_Syntax.decl) list) : (Prims.int) FStarC_SMap.t =
  (let tbl = (FStarC_SMap.create (Prims.parse_int "100")) in
  (FStarC_List.iter (fun d -> (match d with
    | (FStarC_Custard_Syntax.DLet (l)) -> (let tmp = (if (FStarC_Custard_Syntax.is_pure (l).FStarC_Custard_Syntax.dl_eff) then (cheap_expr (l).FStarC_Custard_Syntax.dl_body) else false) in
      let growable = (if tmp then (let tmp1 = (arrow_arity (l).FStarC_Custard_Syntax.dl_ret) in
        (Prims.op_Greater tmp1 (Prims.parse_int "0"))) else false) in
      (match ((l).FStarC_Custard_Syntax.dl_body).FStarC_Custard_Syntax.e with
        | (FStarC_Custard_Syntax.EQual (u__1, u__2)) when growable -> ()
        | (FStarC_Custard_Syntax.EApp ({ FStarC_Custard_Syntax.e = (FStarC_Custard_Syntax.EQual (u__1, u__2)); ty = tmp1; eff = tmp2; _ }, es)) when growable -> (FStarC_List.iter (expr_uses tbl) es)
        | tmp1 -> (expr_uses tbl (l).FStarC_Custard_Syntax.dl_body)
      ))
    | tmp -> ()
  )) prog);
  tbl)

let rec eta_expand_decl__absorb__peel (n : Prims.int) (t : FStarC_Custard_Syntax.cty) (e : FStarC_Custard_Syntax.eff) : ((FStarC_Custard_Syntax.cty * FStarC_Custard_Syntax.eff)) option =
  (if (Prims.op_Less_Equals n (Prims.parse_int "0")) then (Some ((t, e))) else (match t with
    | (FStarC_Custard_Syntax.TArrow (tmp, e', b)) -> (eta_expand_decl__absorb__peel (Prims.op_Minus n (Prims.parse_int "1")) b e')
    | tmp -> None
  ))

let rec eta_expand_decl__absorb (n : Prims.int) (bs : (FStarC_Custard_Syntax.binder) list) (body : FStarC_Custard_Syntax.expr) (ret : FStarC_Custard_Syntax.cty) (ef : FStarC_Custard_Syntax.eff) : ((FStarC_Custard_Syntax.binder) list * FStarC_Custard_Syntax.expr * FStarC_Custard_Syntax.cty * FStarC_Custard_Syntax.eff) =
  (match (body).FStarC_Custard_Syntax.e with
    | (FStarC_Custard_Syntax.EFun (lbs, lbody)) when ((match lbs with
      | (hd :: tl) -> true
      | tmp -> false
    ) && (Prims.op_Less_Equals (FStarC_List.length lbs) n)) -> (let tmp = (eta_expand_decl__absorb__peel (FStarC_List.length lbs) ret ef) in
      (match tmp with
        | (Some ((ret', ef'))) -> (eta_expand_decl__absorb (Prims.op_Minus n (FStarC_List.length lbs)) (FStarC_List.op_At bs lbs) lbody ret' ef')
        | None -> (bs, body, ret, ef)
      ))
    | tmp -> (bs, body, ret, ef)
  )

let rec eta_expand_decl__go (n : Prims.int) (bs : (FStarC_Custard_Syntax.binder) list) (body : FStarC_Custard_Syntax.expr) (ret : FStarC_Custard_Syntax.cty) (ef : FStarC_Custard_Syntax.eff) : ((FStarC_Custard_Syntax.binder) list * FStarC_Custard_Syntax.expr * FStarC_Custard_Syntax.cty * FStarC_Custard_Syntax.eff) =
  (if (Prims.op_Less_Equals n (Prims.parse_int "0")) then (bs, body, ret, ef) else (match ret with
    | (FStarC_Custard_Syntax.TArrow (a, e, b)) -> (let v = (rename "eta") in
      let arg = (FStarC_Custard_Syntax.mk (FStarC_Custard_Syntax.EVar (v)) a FStarC_Custard_Syntax.E_Pure) in
      let body' = (match (body).FStarC_Custard_Syntax.e with
          | (FStarC_Custard_Syntax.EApp (f, args)) -> (FStarC_Custard_Syntax.mk (FStarC_Custard_Syntax.EApp (f, (FStarC_List.op_At args (arg :: [])))) b e)
          | tmp -> (FStarC_Custard_Syntax.mk (FStarC_Custard_Syntax.EApp (body, (arg :: []))) b e)
        ) in
      (eta_expand_decl__go (Prims.op_Minus n (Prims.parse_int "1")) (FStarC_List.op_At bs ({ FStarC_Custard_Syntax.b_name = v; b_ty = a } :: [])) body' b e))
    | tmp -> (bs, body, ret, ef)
  ))

let eta_expand_decl (tbl : (Prims.int) FStarC_SMap.t) (uses : (Prims.int) FStarC_SMap.t) (l : FStarC_Custard_Syntax.dlet) : FStarC_Custard_Syntax.dlet =
  (let tmp = (FStarC_Custard_Syntax.string_of_name (l).FStarC_Custard_Syntax.dl_name) in
  let tmp1 = (FStarC_SMap.try_find uses tmp) in
  let absorb_room = (match tmp1 with
      | (Some (k)) -> (let r = (Prims.op_Minus k (FStarC_List.length (l).FStarC_Custard_Syntax.dl_binders)) in
        (if (Prims.op_Less r (Prims.parse_int "0")) then (Prims.parse_int "0") else r))
      | None -> (arrow_arity (l).FStarC_Custard_Syntax.dl_ret)
    ) in
