    (if tmp then (let tmp1 = (FStarC_Custard_Syntax.string_of_name (FStarC_Custard_Syntax.name_of_decl d)) in
    (tmp1 :: [])) else []))) prog) in
  (if (match seeds with
    | [] -> true
    | tmp -> false
