  (let tbl = (FStarC_SMap.create (Prims.parse_int "100")) in
  let full = (fun dl r -> (let tmp = (FStarC_List.map (fun b -> (b).FStarC_Custard_Syntax.b_ty) (dl).FStarC_Custard_Syntax.dl_binders) in
