          ) in
        let tmp2 = (narrow_rets__has_any cur) in
        (if tmp2 then (let r = ((narrow_rets__body_ty tbl) (dl).FStarC_Custard_Syntax.dl_body) in
        let tmp3 = (narrow_rets__has_any r) in
        let tmp4 = (not tmp3) in
        (if tmp4 then (let tmp5 = (full dl r) in
        (FStarC_SMap.add tbl key tmp5);
        ((changed) := true)) else ())) else ()))
      | tmp1 -> ()
    )) prog)) in
  ((narrow_rets__loop changed round) (Prims.parse_int "20"));
  (FStarC_List.map (fun d -> (match d with
    | (FStarC_Custard_Syntax.DLet (dl)) when (if (match (dl).FStarC_Custard_Syntax.dl_typars with
      | [] -> true
      | tmp -> false
    ) then (narrow_rets__has_any (dl).FStarC_Custard_Syntax.dl_ret) else false) -> (let tmp = (FStarC_Custard_Syntax.string_of_name (dl).FStarC_Custard_Syntax.dl_name) in
      let tmp1 = (FStarC_SMap.try_find tbl tmp) in
      (match tmp1 with
        | (Some (t)) -> (match (peel_arrows (FStarC_List.length (dl).FStarC_Custard_Syntax.dl_binders) t) with
            | (Some ((tmp2, r))) when (let tmp3 = (narrow_rets__has_any r) in
            (not tmp3)) -> (FStarC_Custard_Syntax.DLet ({ FStarC_Custard_Syntax.dl_name = (dl).FStarC_Custard_Syntax.dl_name;
                dl_typars = (dl).FStarC_Custard_Syntax.dl_typars;
                dl_binders = (dl).FStarC_Custard_Syntax.dl_binders;
                dl_ret = r;
                dl_eff = (dl).FStarC_Custard_Syntax.dl_eff;
                dl_body = (dl).FStarC_Custard_Syntax.dl_body;
                dl_flags = (dl).FStarC_Custard_Syntax.dl_flags }))
            | tmp2 -> d
          )
        | None -> d
      ))
    | d1 -> d1
  )) prog))

let rec refutable (infos : (ctor_info) FStarC_SMap.t) (p : FStarC_Custard_Syntax.pat) : bool =
  (match p with
    | (FStarC_Custard_Syntax.PVar (tmp)) -> false
    | FStarC_Custard_Syntax.PWild -> false
    | (FStarC_Custard_Syntax.PConst (tmp)) -> true
    | (FStarC_Custard_Syntax.POr (tmp)) -> true
    | (FStarC_Custard_Syntax.PTuple (ps)) -> (FStarC_List.existsb (refutable infos) ps)
    | (FStarC_Custard_Syntax.PRecord (tmp, fps)) -> (FStarC_List.existsb (fun tmp1 -> (match tmp1 with
        | (tmp2, q) -> (refutable infos q)
      )) fps)
    | (FStarC_Custard_Syntax.PCtor (cn, ps)) -> (let tmp = (FStarC_Custard_Syntax.string_of_name cn) in
      let tmp1 = (FStarC_SMap.try_find infos tmp) in
      (match tmp1 with
        | (Some (ci)) when ((=) (ci).ci_count (Prims.parse_int "1")) -> (FStarC_List.existsb (refutable infos) ps)
        | tmp2 -> true
      ))
  )

let inst_fields (ci : ctor_info) (sc : (FStarC_Custard_Syntax.cty) option) : ((string * FStarC_Custard_Syntax.cty)) list =
  (match sc with
    | (Some ((FStarC_Custard_Syntax.TApp (tmp, args)))) when ((=) (FStarC_List.length args) (FStarC_List.length (ci).ci_params)) -> (let sub_ = (FStarC_List.zip (ci).ci_params args) in
      (FStarC_List.map (fun tmp1 -> (match tmp1 with
        | (f, t) -> (let tmp2 = (FStarC_Custard_Syntax.subst_cty sub_ t) in
          (f, tmp2))
      )) (ci).ci_fields))
    | tmp -> (ci).ci_fields
  )

let tuple_fields (sc : (FStarC_Custard_Syntax.cty) option) (ps : (FStarC_Custard_Syntax.pat) list) : (FStarC_Custard_Syntax.cty) list =
  (match sc with
    | (Some ((FStarC_Custard_Syntax.TTuple (ts)))) when ((=) (FStarC_List.length ts) (FStarC_List.length ps)) -> ts
    | tmp -> (FStarC_List.map (fun tmp1 -> (FStarC_Custard_Syntax.TVar ("?"))) ps)
  )

let rec split_any (infos : (ctor_info) FStarC_SMap.t) (fb : (FStarC_Custard_Syntax.expr) option) (sc : (FStarC_Custard_Syntax.cty) option) (p : FStarC_Custard_Syntax.pat) (body : FStarC_Custard_Syntax.expr) : (FStarC_Custard_Syntax.pat * FStarC_Custard_Syntax.expr) =
  (let simple = (fun p1 -> ((match p1 with
      | (FStarC_Custard_Syntax.PVar (u__0)) -> true
      | tmp -> false
    ) || (match p1 with
      | FStarC_Custard_Syntax.PWild -> true
      | tmp -> false
    ))) in
  let field = (fun t p1 body1 -> (if ((match t with
      | FStarC_Custard_Syntax.TAny -> true
      | tmp -> false
    ) && (not (simple p1))) then (let v = (rename "any") in
    let sc1 = (FStarC_Custard_Syntax.mk (FStarC_Custard_Syntax.ECoerce ((FStarC_Custard_Syntax.mk (FStarC_Custard_Syntax.EVar (v)) FStarC_Custard_Syntax.TAny FStarC_Custard_Syntax.E_Pure), FStarC_Custard_Syntax.TAny)) FStarC_Custard_Syntax.TAny FStarC_Custard_Syntax.E_Pure) in
    let need = (refutable infos p1) in
    let tmp = (split_any infos fb (Some (FStarC_Custard_Syntax.TAny)) p1 body1) in
    (match tmp with
      | (p2, body2) -> (let brs = ((p2, None, body2) :: (match fb with
            | (Some (e)) when need -> ((FStarC_Custard_Syntax.PWild, None, e) :: [])
            | tmp1 -> []
          )) in
        ((FStarC_Custard_Syntax.PVar (v)), { FStarC_Custard_Syntax.e = (FStarC_Custard_Syntax.EMatch (sc1, brs));
          ty = (body2).FStarC_Custard_Syntax.ty;
          eff = (body2).FStarC_Custard_Syntax.eff }))
    )) else (split_any infos fb (Some (t)) p1 body1))) in
  let many = (fun ts ps body1 -> (FStarC_List.fold_right (fun tmp tmp1 -> (match (tmp, tmp1) with
      | ((t, p1), (ps1, body2)) -> (let tmp2 = (field t p1 body2) in
        (match tmp2 with
          | (p2, body3) -> ((p2 :: ps1), body3)
        ))
    )) (FStarC_List.zip ts ps) ([], body1))) in
  (match p with
    | (FStarC_Custard_Syntax.PCtor (cn, ps)) -> (let tmp = (FStarC_Custard_Syntax.string_of_name cn) in
      let tmp1 = (FStarC_SMap.try_find infos tmp) in
      (match tmp1 with
        | (Some (ci)) when ((=) (FStarC_List.length (ci).ci_fields) (FStarC_List.length ps)) -> (let tmp2 = (inst_fields ci sc) in
          let tmp3 = (FStarC_List.map Custard_FStar_Pervasives_Native.fStar_Pervasives_Native_snd tmp2) in
          let tmp4 = (many tmp3 ps body) in
          (match tmp4 with
            | (ps1, body1) -> ((FStarC_Custard_Syntax.PCtor (cn, ps1)), body1)
          ))
        | tmp2 -> (p, body)
      ))
    | (FStarC_Custard_Syntax.PRecord (tn, fps)) -> (let tmp = (FStarC_Custard_Syntax.string_of_name tn) in
      let tmp1 = (FStarC_SMap.try_find infos tmp) in
      (match tmp1 with
        | (Some (ci)) -> (let fs = (inst_fields ci sc) in
          let ts = (FStarC_List.map (fun tmp2 -> (match tmp2 with
              | (f, tmp3) -> (let tmp4 = (FStarC_List.tryFind (fun tmp4 -> (match tmp4 with
                    | (g, tmp5) -> ((=) g f)
                  )) fs) in
                (match tmp4 with
                  | (Some ((tmp5, t))) -> t
                  | None -> (FStarC_Custard_Syntax.TVar ("?"))
                ))
            )) fps) in
          let tmp2 = (FStarC_List.map Custard_FStar_Pervasives_Native.fStar_Pervasives_Native_snd fps) in
          let tmp3 = (many ts tmp2 body) in
          (match tmp3 with
            | (ps, body1) -> (let tmp4 = (FStarC_List.map Custard_FStar_Pervasives_Native.fStar_Pervasives_Native_fst fps) in
              let tmp5 = (FStarC_List.zip tmp4 ps) in
              let tmp6 = (tn, tmp5) in
              let tmp7 = (FStarC_Custard_Syntax.PRecord ((match tmp6 with (custard_tup, _) -> custard_tup), (match tmp6 with (_, custard_tup) -> custard_tup))) in
              (tmp7, body1))
          ))
        | None -> (p, body)
      ))
    | (FStarC_Custard_Syntax.PTuple (ps)) -> (let tmp = (tuple_fields sc ps) in
      let tmp1 = (many tmp ps body) in
      (match tmp1 with
        | (ps1, body1) -> ((FStarC_Custard_Syntax.PTuple (ps1)), body1)
      ))
    | (FStarC_Custard_Syntax.POr (tmp)) -> (p, body)
    | (FStarC_Custard_Syntax.PVar (tmp)) -> (p, body)
    | FStarC_Custard_Syntax.PWild -> (p, body)
    | (FStarC_Custard_Syntax.PConst (tmp)) -> (p, body)
  ))

let rec splits_refutably (infos : (ctor_info) FStarC_SMap.t) (sc : (FStarC_Custard_Syntax.cty) option) (p : FStarC_Custard_Syntax.pat) : bool =
  (let simple = (fun q -> ((match q with
      | (FStarC_Custard_Syntax.PVar (u__0)) -> true
      | tmp -> false
    ) || (match q with
      | FStarC_Custard_Syntax.PWild -> true
      | tmp -> false
    ))) in
  let field = (fun t q -> (let tmp = (if ((match t with
        | FStarC_Custard_Syntax.TAny -> true
        | tmp -> false
      ) && (not (simple q))) then (refutable infos q) else false) in
    (if tmp then true else (splits_refutably infos (Some (t)) q)))) in
  let many = (fun ts ps -> (FStarC_List.existsb (fun tmp -> (match tmp with
      | (t, q) -> (field t q)
    )) (FStarC_List.zip ts ps))) in
  (match p with
    | (FStarC_Custard_Syntax.PCtor (cn, ps)) -> (let tmp = (FStarC_Custard_Syntax.string_of_name cn) in
      let tmp1 = (FStarC_SMap.try_find infos tmp) in
      (match tmp1 with
        | (Some (ci)) when ((=) (FStarC_List.length (ci).ci_fields) (FStarC_List.length ps)) -> (let tmp2 = (inst_fields ci sc) in
          let tmp3 = (FStarC_List.map Custard_FStar_Pervasives_Native.fStar_Pervasives_Native_snd tmp2) in
          (many tmp3 ps))
        | tmp2 -> false
      ))
    | (FStarC_Custard_Syntax.PRecord (tn, fps)) -> (let tmp = (FStarC_Custard_Syntax.string_of_name tn) in
      let tmp1 = (FStarC_SMap.try_find infos tmp) in
      (match tmp1 with
        | (Some (ci)) -> (let fs = (inst_fields ci sc) in
          (FStarC_List.existsb (fun tmp2 -> (match tmp2 with
            | (f, q) -> (let tmp3 = (FStarC_List.tryFind (fun tmp3 -> (match tmp3 with
                  | (g, tmp4) -> ((=) g f)
                )) fs) in
              (match tmp3 with
                | (Some ((tmp4, t))) -> (field t q)
                | None -> (field (FStarC_Custard_Syntax.TVar ("?")) q)
              ))
          )) fps))
        | None -> false
      ))
    | (FStarC_Custard_Syntax.PTuple (ps)) -> (let tmp = (tuple_fields sc ps) in
      (many tmp ps))
    | (FStarC_Custard_Syntax.POr (tmp)) -> false
    | (FStarC_Custard_Syntax.PVar (tmp)) -> false
    | FStarC_Custard_Syntax.PWild -> false
    | (FStarC_Custard_Syntax.PConst (tmp)) -> false
  ))

let rec split_any_expr__go (br : ((FStarC_Custard_Syntax.cty) option -> ((FStarC_Custard_Syntax.expr) option -> ((FStarC_Custard_Syntax.pat * (FStarC_Custard_Syntax.expr) option * FStarC_Custard_Syntax.expr) -> (FStarC_Custard_Syntax.pat * (FStarC_Custard_Syntax.expr) option * FStarC_Custard_Syntax.expr))))) (x : FStarC_Custard_Syntax.expr) (scty : (FStarC_Custard_Syntax.cty) option) (sv : (unit -> FStarC_Custard_Syntax.expr)) (bs : ((FStarC_Custard_Syntax.pat * (FStarC_Custard_Syntax.expr) option * FStarC_Custard_Syntax.expr)) list) : ((FStarC_Custard_Syntax.pat * (FStarC_Custard_Syntax.expr) option * FStarC_Custard_Syntax.expr)) list =
  (match bs with
    | [] -> []
    | (b0 :: rest) -> (let rest1 = ((split_any_expr__go br x scty sv) rest) in
      let fb = (match rest1 with
          | [] -> None
          | tmp -> (let tmp1 = (sv ()) in
            let tmp2 = (tmp1, rest1) in
            let tmp3 = (FStarC_Custard_Syntax.EMatch ((match tmp2 with (custard_tup, _) -> custard_tup), (match tmp2 with (_, custard_tup) -> custard_tup))) in
            let tmp4 = (FStarC_Custard_Syntax.mk tmp3 (x).FStarC_Custard_Syntax.ty (x).FStarC_Custard_Syntax.eff) in
            (Some (tmp4)))
        ) in
      let tmp = (br scty fb b0) in
      (tmp :: rest1))
  )

let rec split_any_expr (infos : (ctor_info) FStarC_SMap.t) (x : FStarC_Custard_Syntax.expr) : FStarC_Custard_Syntax.expr =
  (let g = (split_any_expr infos) in
  let br = (fun sc fb b0 -> (match b0 with
      | (p, gd, b) -> (let b1 = (g b) in
        (match gd with
          | (Some (gd1)) -> (let tmp = (g gd1) in
            let tmp1 = (Some (tmp)) in
            (p, tmp1, b1))
          | None -> (let tmp = (split_any infos fb sc p b1) in
            (match tmp with
              | (p1, b2) -> (p1, None, b2)
            ))
        ))
    )) in
  let branches = (fun sc x1 brs -> (let scty = (Some ((sc).FStarC_Custard_Syntax.ty)) in
    let needed = (FStarC_List.existsb (fun tmp -> (match tmp with
        | (p, gd, tmp1) -> (if (match gd with
            | None -> true
            | tmp2 -> false
          ) then (splits_refutably infos scty p) else false)
      )) brs) in
    (if (not needed) then (let tmp = (FStarC_List.map (br scty None) brs) in
    let tmp1 = (sc, tmp) in
    let tmp2 = (FStarC_Custard_Syntax.EMatch ((match tmp1 with (custard_tup, _) -> custard_tup), (match tmp1 with (_, custard_tup) -> custard_tup))) in
    { FStarC_Custard_Syntax.e = tmp2;
      ty = (x1).FStarC_Custard_Syntax.ty;
      eff = (x1).FStarC_Custard_Syntax.eff }) else (let v = (rename "sc") in
    let sv = (fun tmp -> (FStarC_Custard_Syntax.mk (FStarC_Custard_Syntax.EVar (v)) (sc).FStarC_Custard_Syntax.ty FStarC_Custard_Syntax.E_Pure)) in
    let brs1 = ((split_any_expr__go br x1 scty sv) brs) in
    let tmp = (sv ()) in
    let tmp1 = (tmp, brs1) in
    let tmp2 = (FStarC_Custard_Syntax.EMatch ((match tmp1 with (custard_tup, _) -> custard_tup), (match tmp1 with (_, custard_tup) -> custard_tup))) in
    let tmp3 = (FStarC_Custard_Syntax.mk tmp2 (x1).FStarC_Custard_Syntax.ty (x1).FStarC_Custard_Syntax.eff) in
    let tmp4 = (v, (sc).FStarC_Custard_Syntax.ty, sc, tmp3) in
    let tmp5 = (FStarC_Custard_Syntax.ELet ((match tmp4 with (custard_tup, _, _, _) -> custard_tup), (match tmp4 with (_, custard_tup, _, _) -> custard_tup), (match tmp4 with (_, _, custard_tup, _) -> custard_tup), (match tmp4 with (_, _, _, custard_tup) -> custard_tup))) in
    { FStarC_Custard_Syntax.e = tmp5;
      ty = (x1).FStarC_Custard_Syntax.ty;
      eff = (x1).FStarC_Custard_Syntax.eff })))) in
  (match (x).FStarC_Custard_Syntax.e with
    | (FStarC_Custard_Syntax.EMatch (s, brs)) -> (let tmp = (g s) in
      (branches tmp x brs))
    | (FStarC_Custard_Syntax.ETry (s, brs)) -> (let tmp = (g s) in
      let tmp1 = (FStarC_List.map (br (Some (FStarC_Custard_Syntax.TExn)) None) brs) in
      let tmp2 = (tmp, tmp1) in
      let tmp3 = (FStarC_Custard_Syntax.ETry ((match tmp2 with (custard_tup, _) -> custard_tup), (match tmp2 with (_, custard_tup) -> custard_tup))) in
      { FStarC_Custard_Syntax.e = tmp3;
        ty = (x).FStarC_Custard_Syntax.ty;
        eff = (x).FStarC_Custard_Syntax.eff })
    | tmp -> (FStarC_Custard_Syntax.map_children g x)
  ))

let split_any_decls (prog : (FStarC_Custard_Syntax.decl) list) : (FStarC_Custard_Syntax.decl) list =
  (let tmp = (with_imports prog) in
  let infos = (ctor_infos tmp) in
  (FStarC_List.map (fun d -> (match d with
    | (FStarC_Custard_Syntax.DLet (dl)) -> (let tmp1 = (split_any_expr infos (dl).FStarC_Custard_Syntax.dl_body) in
      let tmp2 = { FStarC_Custard_Syntax.dl_name = (dl).FStarC_Custard_Syntax.dl_name;
          dl_typars = (dl).FStarC_Custard_Syntax.dl_typars;
          dl_binders = (dl).FStarC_Custard_Syntax.dl_binders;
          dl_ret = (dl).FStarC_Custard_Syntax.dl_ret;
          dl_eff = (dl).FStarC_Custard_Syntax.dl_eff;
          dl_body = tmp1;
          dl_flags = (dl).FStarC_Custard_Syntax.dl_flags } in
      (FStarC_Custard_Syntax.DLet (tmp2)))
    | d1 -> d1
  )) prog))

let rec coerce_prog__build (dl : FStarC_Custard_Syntax.dlet) (bs : (FStarC_Custard_Syntax.binder) list) : FStarC_Custard_Syntax.cty =
  (match bs with
    | [] -> (dl).FStarC_Custard_Syntax.dl_ret
    | (b :: bs1) -> (FStarC_Custard_Syntax.TArrow ((b).FStarC_Custard_Syntax.b_ty, FStarC_Custard_Syntax.E_Pure, ((coerce_prog__build dl) bs1)))
  )

let rec coerce_prog__scrutinee_of (owner_of : (string -> (FStarC_Custard_Syntax.cty) option)) (ty_of_const : (FStarC_Custard_Syntax.constant -> FStarC_Custard_Syntax.cty)) (brs : ((FStarC_Custard_Syntax.pat * (FStarC_Custard_Syntax.expr) option * FStarC_Custard_Syntax.expr)) list) : (FStarC_Custard_Syntax.cty) option =
  (match brs with
    | [] -> None
    | ((p, tmp, tmp1) :: brs1) -> (match p with
        | (FStarC_Custard_Syntax.PCtor (n, tmp2)) -> (let tmp3 = (FStarC_Custard_Syntax.string_of_name n) in
          (owner_of tmp3))
        | (FStarC_Custard_Syntax.PRecord (n, tmp2)) -> (let tmp3 = (FStarC_Custard_Syntax.string_of_name n) in
          (owner_of tmp3))
        | (FStarC_Custard_Syntax.PConst (c)) -> (Some ((ty_of_const c)))
        | tmp2 -> ((coerce_prog__scrutinee_of owner_of ty_of_const) brs1)
      )
  )

let rec coerce_prog__has_any (c : FStarC_Custard_Syntax.cty) : bool =
  (match c with
    | FStarC_Custard_Syntax.TAny -> true
    | (FStarC_Custard_Syntax.TArrow (a, tmp, b)) -> (let tmp1 = (coerce_prog__has_any a) in
      (if tmp1 then true else (coerce_prog__has_any b)))
    | (FStarC_Custard_Syntax.TApp (tmp, args)) -> (FStarC_List.existsb coerce_prog__has_any args)
    | (FStarC_Custard_Syntax.TTuple (cs)) -> (FStarC_List.existsb coerce_prog__has_any cs)
    | (FStarC_Custard_Syntax.TBuf (c1)) -> (coerce_prog__has_any c1)
    | (FStarC_Custard_Syntax.TRef (c1)) -> (coerce_prog__has_any c1)
    | (FStarC_Custard_Syntax.TInline (c1)) -> (coerce_prog__has_any c1)
    | (FStarC_Custard_Syntax.TVar (tmp)) -> false
    | (FStarC_Custard_Syntax.TInt (u__1, u__2)) -> false
    | (FStarC_Custard_Syntax.TFloat (tmp)) -> false
    | FStarC_Custard_Syntax.TUnit -> false
    | FStarC_Custard_Syntax.TExn -> false
    | (FStarC_Custard_Syntax.TConst (tmp)) -> false
  )

let rec coerce_prog__bind_pat (fields_of_ : (string -> ((FStarC_Custard_Syntax.cty) option -> ((string * FStarC_Custard_Syntax.cty)) list))) (field_of : (string -> ((FStarC_Custard_Syntax.cty) option -> (string -> (FStarC_Custard_Syntax.cty) option)))) (extend : (((FStarC_Custard_Syntax.cty) option) FStarC_SMap.t -> (string -> ((FStarC_Custard_Syntax.cty) option -> ((FStarC_Custard_Syntax.cty) option) FStarC_SMap.t)))) (env : ((FStarC_Custard_Syntax.cty) option) FStarC_SMap.t) (sc : (FStarC_Custard_Syntax.cty) option) (p : FStarC_Custard_Syntax.pat) : ((FStarC_Custard_Syntax.cty) option) FStarC_SMap.t =
  (match p with
    | FStarC_Custard_Syntax.PWild -> env
    | (FStarC_Custard_Syntax.PConst (tmp)) -> env
    | (FStarC_Custard_Syntax.PVar (v)) -> (extend env v sc)
    | (FStarC_Custard_Syntax.POr (ps)) -> (FStarC_List.fold_left (fun env1 p1 -> ((coerce_prog__bind_pat fields_of_ field_of extend) env1 sc p1)) env ps)
    | (FStarC_Custard_Syntax.PTuple (ps)) -> (let ts = (match sc with
          | (Some ((FStarC_Custard_Syntax.TTuple (ts)))) when ((=) (FStarC_List.length ts) (FStarC_List.length ps)) -> (FStarC_List.map (fun u__eta -> (Some (u__eta))) ts)
          | tmp -> (FStarC_List.map (fun tmp1 -> None) ps)
        ) in
      (FStarC_List.fold_left (fun env1 tmp -> (match tmp with
        | (t, p1) -> ((coerce_prog__bind_pat fields_of_ field_of extend) env1 t p1)
      )) env (FStarC_List.zip ts ps)))
    | (FStarC_Custard_Syntax.PCtor (n, ps)) -> (let tmp = (FStarC_Custard_Syntax.string_of_name n) in
      let fs = (fields_of_ tmp sc) in
      (if ((=) (FStarC_List.length fs) (FStarC_List.length ps)) then (FStarC_List.fold_left (fun env1 tmp1 -> (match tmp1 with
        | ((tmp2, t), p1) -> ((coerce_prog__bind_pat fields_of_ field_of extend) env1 (Some (t)) p1)
      )) env (FStarC_List.zip fs ps)) else (FStarC_List.fold_left (fun env1 p1 -> ((coerce_prog__bind_pat fields_of_ field_of extend) env1 None p1)) env ps)))
    | (FStarC_Custard_Syntax.PRecord (n, fps)) -> (FStarC_List.fold_left (fun env1 tmp -> (match tmp with
        | (f, p1) -> (let tmp1 = (FStarC_Custard_Syntax.string_of_name n) in
          let tmp2 = (field_of tmp1 sc f) in
          ((coerce_prog__bind_pat fields_of_ field_of extend) env1 tmp2 p1))
