    | (FStarC_Custard_Syntax.DLet (dl)) -> (let env = (FStarC_SMap.create (Prims.parse_int "20")) in
      (FStarC_List.iter (fun b -> (FStarC_SMap.add env (b).FStarC_Custard_Syntax.b_name (Some ((b).FStarC_Custard_Syntax.b_ty)))) (dl).FStarC_Custard_Syntax.dl_binders);
      let tmp = ((coerce_prog__check sig_of owner_of fields_of_ field_of ty_of_const trust concrete_shape lookup extend first cond_ty pushes_down coerce) env (Some ((dl).FStarC_Custard_Syntax.dl_ret)) (dl).FStarC_Custard_Syntax.dl_body) in
      let tmp1 = { FStarC_Custard_Syntax.dl_name = (dl).FStarC_Custard_Syntax.dl_name;
          dl_typars = (dl).FStarC_Custard_Syntax.dl_typars;
          dl_binders = (dl).FStarC_Custard_Syntax.dl_binders;
          dl_ret = (dl).FStarC_Custard_Syntax.dl_ret;
          dl_eff = (dl).FStarC_Custard_Syntax.dl_eff;
          dl_body = tmp;
          dl_flags = (dl).FStarC_Custard_Syntax.dl_flags } in
      (FStarC_Custard_Syntax.DLet (tmp1)))
    | d1 -> d1
  )) prog))

let rec unit_args_expr (x : FStarC_Custard_Syntax.expr) : FStarC_Custard_Syntax.expr =
  (let g = unit_args_expr in
  let arg = (fun acc e -> (let e1 = (g e) in
    (if (not (match (e1).FStarC_Custard_Syntax.ty with
      | FStarC_Custard_Syntax.TUnit -> true
      | tmp -> false
    )) then e1 else (match (e1).FStarC_Custard_Syntax.e with
      | (FStarC_Custard_Syntax.EConst (FStarC_Custard_Syntax.CUnit)) -> e1
      | (FStarC_Custard_Syntax.EAbort (tmp)) -> e1
      | tmp -> (if (FStarC_Custard_Syntax.is_pure (e1).FStarC_Custard_Syntax.eff) then { FStarC_Custard_Syntax.e = (FStarC_Custard_Syntax.EConst (FStarC_Custard_Syntax.CUnit));
          ty = (e1).FStarC_Custard_Syntax.ty;
          eff = (e1).FStarC_Custard_Syntax.eff } else (let tmp1 = (FStarC_GenSym.next_id ()) in
        let v = (FStarC_Custard_Syntax.uniq "tmp" tmp1) in
        let tmp2 = (!(acc)) in
        let tmp3 = ((v, (e1).FStarC_Custard_Syntax.ty, e1) :: tmp2) in
        ((acc) := tmp3);
        { FStarC_Custard_Syntax.e = (FStarC_Custard_Syntax.EConst (FStarC_Custard_Syntax.CUnit));
          ty = (e1).FStarC_Custard_Syntax.ty;
          eff = FStarC_Custard_Syntax.E_Pure }))
    )))) in
  let with_hoists = (fun k -> (let acc = (ref []) in
    let body = (k acc) in
    let tmp = (!(acc)) in
    (FStarC_List.fold_left (fun body1 tmp1 -> (match tmp1 with
      | (v, t, e) -> { FStarC_Custard_Syntax.e = (FStarC_Custard_Syntax.ELet (v, t, e, body1));
          ty = (body1).FStarC_Custard_Syntax.ty;
          eff = (body1).FStarC_Custard_Syntax.eff }
    )) body tmp))) in
  (match (x).FStarC_Custard_Syntax.e with
    | (FStarC_Custard_Syntax.EApp (h, es)) -> (with_hoists (fun acc -> (let h1 = (g h) in
      let es1 = (FStarC_List.map (arg acc) es) in
      { FStarC_Custard_Syntax.e = (FStarC_Custard_Syntax.EApp (h1, es1));
        ty = (x).FStarC_Custard_Syntax.ty;
        eff = (x).FStarC_Custard_Syntax.eff })))
    | (FStarC_Custard_Syntax.ETuple (es)) -> (with_hoists (fun acc -> (let tmp = (FStarC_List.map (arg acc) es) in
      let tmp1 = (FStarC_Custard_Syntax.ETuple (tmp)) in
      { FStarC_Custard_Syntax.e = tmp1;
        ty = (x).FStarC_Custard_Syntax.ty;
        eff = (x).FStarC_Custard_Syntax.eff })))
    | (FStarC_Custard_Syntax.EOp (o, es)) -> (with_hoists (fun acc -> (let tmp = (FStarC_List.map (arg acc) es) in
      let tmp1 = (o, tmp) in
      let tmp2 = (FStarC_Custard_Syntax.EOp ((match tmp1 with (custard_tup, _) -> custard_tup), (match tmp1 with (_, custard_tup) -> custard_tup))) in
      { FStarC_Custard_Syntax.e = tmp2;
        ty = (x).FStarC_Custard_Syntax.ty;
        eff = (x).FStarC_Custard_Syntax.eff })))
    | (FStarC_Custard_Syntax.ECtor (n, es)) -> (with_hoists (fun acc -> (let tmp = (FStarC_List.map (arg acc) es) in
      let tmp1 = (n, tmp) in
      let tmp2 = (FStarC_Custard_Syntax.ECtor ((match tmp1 with (custard_tup, _) -> custard_tup), (match tmp1 with (_, custard_tup) -> custard_tup))) in
      { FStarC_Custard_Syntax.e = tmp2;
        ty = (x).FStarC_Custard_Syntax.ty;
        eff = (x).FStarC_Custard_Syntax.eff })))
    | (FStarC_Custard_Syntax.ERecord (n, fs)) -> (with_hoists (fun acc -> (let tmp = (FStarC_List.map (fun tmp -> (match tmp with
          | (f, e) -> (let tmp1 = (arg acc e) in
            (f, tmp1))
        )) fs) in
      let tmp1 = (n, tmp) in
      let tmp2 = (FStarC_Custard_Syntax.ERecord ((match tmp1 with (custard_tup, _) -> custard_tup), (match tmp1 with (_, custard_tup) -> custard_tup))) in
      { FStarC_Custard_Syntax.e = tmp2;
        ty = (x).FStarC_Custard_Syntax.ty;
        eff = (x).FStarC_Custard_Syntax.eff })))
    | tmp -> (FStarC_Custard_Syntax.map_children g x)
  ))

let unit_args (prog : (FStarC_Custard_Syntax.decl) list) : (FStarC_Custard_Syntax.decl) list =
  (FStarC_List.map (fun d -> (match d with
    | (FStarC_Custard_Syntax.DLet (dl)) -> (let tmp = (unit_args_expr (dl).FStarC_Custard_Syntax.dl_body) in
      let tmp1 = { FStarC_Custard_Syntax.dl_name = (dl).FStarC_Custard_Syntax.dl_name;
          dl_typars = (dl).FStarC_Custard_Syntax.dl_typars;
          dl_binders = (dl).FStarC_Custard_Syntax.dl_binders;
          dl_ret = (dl).FStarC_Custard_Syntax.dl_ret;
          dl_eff = (dl).FStarC_Custard_Syntax.dl_eff;
          dl_body = tmp;
          dl_flags = (dl).FStarC_Custard_Syntax.dl_flags } in
      (FStarC_Custard_Syntax.DLet (tmp1)))
    | d1 -> d1
  )) prog)

let run (imports : (FStarC_Custard_Syntax.decl) list) (vd : FStarC_Custard_Syntax.verdicts) (prog : (FStarC_Custard_Syntax.decl) list) : (FStarC_Custard_Syntax.decl) list =
  (let pass = (fun n f p -> (FStarC_Custard_Prof.timed (Prims.strcat "s." n) (fun tmp -> (f p)))) in
  ((imported_types) := imports);
  let tmp = (with_imports prog) in
  (record_ctor_tables tmp);
  let prog1 = (pass "eta_ctors" (eta_ctors vd) prog) in
  let prog2 = (pass "eta_reduce" eta_reduce_decls prog1) in
  let prog3 = (pass "inline" inline_decls prog2) in
  let prog4 = (pass "reduce" (fun prog4 -> (let tmp1 = (forwarder_table prog4) in
    ((forwarders) := tmp1);
    (reduce_decls prog4))) prog3) in
  let prog5 = (pass "prune" prune_decls prog4) in
  let prog6 = (pass "depat" depat_decls prog5) in
  let prog7 = (pass "inline_fields" (inline_fields vd) prog6) in
  let prog8 = (pass "unbuild" unbuild_decls prog7) in
  let simpl_all = (fun prog9 -> (FStarC_List.map (fun d -> (match d with
      | (FStarC_Custard_Syntax.DLet (dl)) -> (let tmp1 = (simpl (dl).FStarC_Custard_Syntax.dl_body) in
        let tmp2 = { FStarC_Custard_Syntax.dl_name = (dl).FStarC_Custard_Syntax.dl_name;
            dl_typars = (dl).FStarC_Custard_Syntax.dl_typars;
            dl_binders = (dl).FStarC_Custard_Syntax.dl_binders;
            dl_ret = (dl).FStarC_Custard_Syntax.dl_ret;
            dl_eff = (dl).FStarC_Custard_Syntax.dl_eff;
            dl_body = tmp1;
            dl_flags = (dl).FStarC_Custard_Syntax.dl_flags } in
        (FStarC_Custard_Syntax.DLet (tmp2)))
      | d1 -> d1
    )) prog9)) in
  let prog9 = (pass "simpl" simpl_all prog8) in
  let tmp1 = (FStarC_List.existsb (fun d -> (match d with
      | (FStarC_Custard_Syntax.DLet (dl)) -> (is_identity dl)
      | tmp1 -> false
    )) prog9) in
  let prog10 = (if tmp1 then (let prog10 = (pass "inline_ids" inline_decls prog9) in
    (pass "simpl_ids" simpl_all prog10)) else prog9) in
  let prog11 = (pass "eta_expand" eta_expand_decls prog10) in
  let prog12 = (pass "eta_rename" eta_rename_decls prog11) in
  let tmp2 = (FStarC_Options.custard_backend ()) in
  let tmp3 = ((=) tmp2 "C") in
  let prog13 = (if tmp3 then (pass "lift_lambdas" lift_lambdas prog12) else prog12) in
  let prog14 = (pass "const_globals" const_globals prog13) in
  let prog15 = (pass "dce" dce prog14) in
  let prog16 = (pass "check_resolved" check_resolved prog15) in
  let prog17 = (pass "propagate_prologues" propagate_prologues prog16) in
  let prog18 = (pass "scc" scc prog17) in
  let prog19 = (pass "records" (records vd) prog18) in
  let prog20 = (pass "narrow_rets" narrow_rets prog19) in
  let prog21 = (pass "split_any" split_any_decls prog20) in
  let prog22 = (pass "coerce" coerce_prog prog21) in
  let tmp4 = (FStarC_Options.custard_backend ()) in
  let tmp5 = (FStarC_List.mem tmp4 ("KrmlC" :: ("KrmlRust" :: []))) in
  (if tmp5 then (pass "unit_args" unit_args prog22) else prog22))

